mapper.select:
SELECT t.TRADE_ID tradeId,/**交易编号**/ t.F_TRADE_ID outTradeId, /*外部成交编号*/ NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetAbbr,/**资产简称**/ t.PS ps,/**交易方向**/ t.TRADE_MARKET tradeMarket,/**交易场所**/ t.TRADE_DATE tradeDate,/**交易日期**/ CASE WHEN t.PS in(#{PS_T01},#{PS_T02}) THEN t.PRIN_AMT ELSE t.TRADE_AMT END AS tradeAmt,/**成交金额**/ t.SHARE_AMT dealNum,/**成交数量**/ t.CCY ccy,/**币种**/ stl.SETTLE_DATE settleDate,/**结算日期**/ CASE t.PS WHEN #{PS_T18} THEN t.FEE_AMT ELSE 0 END subFee,/**认购费**/ CASE t.PS WHEN #{PS_T05} THEN t.FEE_AMT ELSE 0 END purFee,/**申购费**/ CASE t.PS WHEN #{PS_T19} THEN t.FEE_AMT ELSE 0 END redFee,/**赎回费**/ CASE t.PS WHEN #{PS_T24} THEN t.TRADE_AMT ELSE 0 END tradeAmtArrive,/*到账金额*/ nvl(ttfd.FEE_AMT,0) commissionPay,/**应付佣金**/ nvl(ttfd2.FEE_AMT,0) commission,/**佣金**/ t.MY_ACCT_NO trdMyAcctNo,/**资金账户**/ d.GEN_TYPE dataSource /**数据来源**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN TRD_PRODUCT_DEAL_ADD d on t.TRADE_ID = d.TRADE_ID LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE in( #{busiType_06},#{busiType_07}) AND STL.ORDER_TYPE NOT LIKE 'N%' LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_DEAL_ACCOUNTING deal2 ON stl.ORDER_ID = deal2.BUSI_NO LEFT JOIN BOK_BOOKSET bok on (bok.BOOKSET_ID = deal1.BOOKSET_ID) OR (bok.BOOKSET_ID = deal2.BOOKSET_ID) LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd ON ttfd.TRADE_ID = t.TRADE_ID AND ttfd.FEE_TYPE = #{FEE_TYPE_B05} and ttfd.IS_PAY_WITH_TRADE=#{YES_NO_N} LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd2 ON ttfd2.TRADE_ID = t.TRADE_ID AND ttfd2.FEE_TYPE = #{FEE_TYPE_B05} and ttfd2.IS_PAY_WITH_TRADE=#{YES_NO_Y} where t.BUSI_TYPE in (#{busiType_06},#{busiType_07}) AND t.FINPROD_TYPE = #{finprodType}
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) IN
#{finprodId}
and zc.FINPROD_ID IN
#{assetId}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
and t.TRADE_MARKET IN
#{tradeMarket}
AND d.GEN_TYPE IN
#{dataSource}
order by t.TRADE_ID desc

SELECT t.TRADE_ID tradeId,/**交易编号**/ t.F_TRADE_ID outTradeId, /*外部成交编号*/ NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetAbbr,/**资产简称**/ t.PS ps,/**交易方向**/ t.TRADE_MARKET tradeMarket,/**交易场所**/ t.CCY ccy,/**币种**/
t.TRADE_DATE tradeDate,/**交易日期**/ stl.SETTLE_DATE settleDate,/**结算日期**/ t.PRIN_AMT tradeAmt,/**成交金额**/ t.SHARE_AMT dealNum,/**成交数量**/ nvl(t.MY_ACCT_NO,stl.MY_ACCT_NO) trdMyAcctNo,/**资金账户**/ nvl(ttfd.FEE_AMT,0) commissionPay,/**应付佣金**/ nvl(ttfd2.FEE_AMT,0) commission,/**佣金**/ t.TRADE_AMT settleAmt/**结算金额**/
/*认购*/ t.TRADE_DATE applyDate,/**申请日期**/ stl.SETTLE_DATE subSettleDate,/**结算日期**/ t.TRADE_AMT applyAmt,/**申请金额**/ nvl(t.MY_ACCT_NO,stl.MY_ACCT_NO) subMyAcctNo/**资金账户**/
/*申购*/ t.TRADE_DATE purApplyDate,/**申请日期**/ stl.SETTLE_DATE purSettleDate,/**结算日期**/ t.TRADE_AMT purApplyAmt,/**申请金额**/ nvl(t.MY_ACCT_NO,stl.MY_ACCT_NO) purMyAcctNo/**资金账户**/
/*认购确认*/ t.TRADE_DATE subConfirmDate,/**确认日期**/ t.TRADE_AMT subConfirmAmt,/**确认金额**/ t.SHARE_AMT subConfirmNum,/**确认数量**/ t.INT_AMT raiseInterest,/**募集期利息**/ t.FEE_AMT subFee,/**认购费**/ nvl(t.MY_ACCT_NO,stl.MY_ACCT_NO) subConfirmMyAcctNo/**资金账户**/
/*申购确认*/ t.TRADE_DATE purConfirmDate,/**确认日期**/ t.TRADE_AMT purConfirmAmt,/**确认金额**/ t.SHARE_AMT purConfirmNum,/**确认数量**/ t.UNIT_CPRICE purUnitValue,/**单位净值**/ t.INT_AMT interestIncome,/**利息收入**/ t.FEE_AMT purFee,/**申购费**/ nvl(t.MY_ACCT_NO,stl.MY_ACCT_NO) purConfirmMyAcctNo/**资金账户**/
t.TRADE_DATE redConfirmDate,/**确认日期**/ t.TRADE_AMT redConfirmAmt,/**确认金额**/ t.SHARE_AMT redConfirmNum,/**确认数量**/ t.UNIT_CPRICE redUnitValue,/**单位净值**/ t.FEE_AMT redFee,/**赎回费**/ nvl(t.MY_ACCT_NO,stl.MY_ACCT_NO) redMyAcctNo/**资金账户**/
FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE in(#{busiType_06},#{busiType_07}) AND STL.ORDER_TYPE NOT LIKE 'N%' LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_DEAL_ACCOUNTING deal2 ON stl.ORDER_ID = deal2.BUSI_NO LEFT JOIN BOK_BOOKSET bok on (bok.BOOKSET_ID = deal1.BOOKSET_ID) OR (bok.BOOKSET_ID = deal2.BOOKSET_ID) LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd ON ttfd.TRADE_ID = t.TRADE_ID AND ttfd.FEE_TYPE = #{FEE_TYPE_B05} and ttfd.IS_PAY_WITH_TRADE=#{YES_NO_N} LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd2 ON ttfd2.TRADE_ID = t.TRADE_ID AND ttfd2.FEE_TYPE = #{FEE_TYPE_B05} and ttfd2.IS_PAY_WITH_TRADE=#{YES_NO_Y} where t.BUSI_TYPE in (#{busiType_06},#{busiType_07}) and t.TRADE_ID = #{tradeId,jdbcType=VARCHAR} and rownum=1
